use crate::bson_values;
use crate::bson_values::Loaded;
use mongodb::bson::Document;
use mongodb::error::Error;

/// A document of the "audit-log" collection. A field stays `None` until it is set or read.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct AuditLog {
    pub id: Option<String>,
    pub at: Option<chrono::DateTime<chrono::Utc>>,
    pub by: Option<mongodb::bson::Bson>,
    /// As it was read: a change writes only what differs
    pub loaded_document: Loaded,
}

impl AuditLog {
    /// What a document holds.
    pub fn from_document(document: &Document) -> Result<Self, Error> {
        let mut entity = AuditLog {
            id: bson_values::read(document, "_id", bson_values::as_text)?,
            at: bson_values::read(document, "at", bson_values::as_moment)?,
            by: bson_values::read(document, "by", bson_values::as_any)?,
            loaded_document: Loaded::default(),
        };
        entity.loaded_document = Loaded(Some(entity.to_document()?));
        Ok(entity)
    }

    /// Its document: what is None is left out.
    pub fn to_document(&self) -> Result<Document, Error> {
        let mut document = Document::new();
        bson_values::write(&mut document, "_id", &self.id, bson_values::of_text)?;
        bson_values::write(&mut document, "at", &self.at, bson_values::of_moment)?;
        bson_values::write(&mut document, "by", &self.by, bson_values::of_any)?;
        Ok(document)
    }
}

