use crate::bson_values;
use crate::bson_values::Loaded;
use mongodb::bson::Document;
use mongodb::error::Error;

/// A document of the "products" collection. A field stays `None` until it is set or read.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct Product {
    pub id: Option<String>,
    pub sku: Option<String>,
    pub price: Option<rust_decimal::Decimal>,
    pub stock: Option<f64>,
    pub weight: Option<f64>,
    pub big: Option<i64>,
    pub created: Option<chrono::DateTime<chrono::Utc>>,
    pub reference: Option<uuid::Uuid>,
    pub picture: Option<Vec<u8>>,
    pub key: Option<uuid::Uuid>,
    pub pattern: Option<mongodb::bson::Bson>,
    pub patterns: Option<Vec<mongodb::bson::Bson>>,
    pub text: Option<String>,
    pub parts: Option<Vec<ProductPart>>,
    pub low: Option<i64>,
    /// As it was read: a change writes only what differs
    pub loaded_document: Loaded,
}

impl Product {
    /// What a document holds.
    pub fn from_document(document: &Document) -> Result<Self, Error> {
        let mut entity = Product {
            id: bson_values::read(document, "_id", bson_values::as_object_id)?,
            sku: bson_values::read(document, "sku", bson_values::as_text)?,
            price: bson_values::read(document, "price", bson_values::as_decimal)?,
            stock: bson_values::read(document, "stock", bson_values::as_f64)?,
            weight: bson_values::read(document, "weight", bson_values::as_f64)?,
            big: bson_values::read(document, "big", bson_values::as_i64)?,
            created: bson_values::read(document, "created", bson_values::as_moment)?,
            reference: bson_values::read(document, "reference", bson_values::as_uuid)?,
            picture: bson_values::read(document, "picture", bson_values::as_bytes)?,
            key: bson_values::read(document, "key", bson_values::as_uuid)?,
            pattern: bson_values::read(document, "pattern", bson_values::as_any)?,
            patterns: bson_values::read(document, "patterns", bson_values::as_list(bson_values::as_any))?,
            text: bson_values::read(document, "text", bson_values::as_text)?,
            parts: bson_values::read(document, "parts", bson_values::as_list(bson_values::as_nested(ProductPart::from_document)))?,
            low: bson_values::read(document, "low", bson_values::as_i64)?,
            loaded_document: Loaded::default(),
        };
        entity.loaded_document = Loaded(Some(entity.to_document()?));
        Ok(entity)
    }

    /// Its document: what is None is left out.
    pub fn to_document(&self) -> Result<Document, Error> {
        let mut document = Document::new();
        bson_values::write(&mut document, "_id", &self.id, bson_values::of_object_id)?;
        bson_values::write(&mut document, "sku", &self.sku, bson_values::of_text)?;
        bson_values::write(&mut document, "price", &self.price, bson_values::of_decimal)?;
        bson_values::write(&mut document, "stock", &self.stock, bson_values::of_f64)?;
        bson_values::write(&mut document, "weight", &self.weight, bson_values::of_f64)?;
        bson_values::write(&mut document, "big", &self.big, bson_values::of_i64)?;
        bson_values::write(&mut document, "created", &self.created, bson_values::of_moment)?;
        bson_values::write(&mut document, "reference", &self.reference, bson_values::of_uuid)?;
        bson_values::write(&mut document, "picture", &self.picture, bson_values::of_bytes)?;
        bson_values::write(&mut document, "key", &self.key, bson_values::of_uuid)?;
        bson_values::write(&mut document, "pattern", &self.pattern, bson_values::of_any)?;
        bson_values::write(&mut document, "patterns", &self.patterns, bson_values::of_list(bson_values::of_any))?;
        bson_values::write(&mut document, "text", &self.text, bson_values::of_text)?;
        bson_values::write(&mut document, "parts", &self.parts, bson_values::of_list(bson_values::of_nested(ProductPart::to_document)))?;
        bson_values::write(&mut document, "low", &self.low, bson_values::of_i64)?;
        Ok(document)
    }
}

/// A nested document: it is stored with the one that holds it.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct ProductPart {
    pub name: Option<String>,
    pub inner: Option<ProductPartInner>,
}

impl ProductPart {
    /// What a document holds.
    pub fn from_document(document: &Document) -> Result<Self, Error> {
        Ok(ProductPart {
            name: bson_values::read(document, "name", bson_values::as_text)?,
            inner: bson_values::read(document, "inner", bson_values::as_nested(ProductPartInner::from_document))?,
        })
    }

    /// Its document: what is None is left out.
    pub fn to_document(&self) -> Result<Document, Error> {
        let mut document = Document::new();
        bson_values::write(&mut document, "name", &self.name, bson_values::of_text)?;
        bson_values::write(&mut document, "inner", &self.inner, bson_values::of_nested(ProductPartInner::to_document))?;
        Ok(document)
    }
}

/// A nested document: it is stored with the one that holds it.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct ProductPartInner {
    pub deep: Option<mongodb::bson::Bson>,
