/// Where products rows are kept. Services depend only on this trait.
#[async_trait]
pub trait ProductRepository: Send + Sync {
    /// The row with this primary key, or None.
    async fn find_by_id(&self, id: String) -> Result<Option<Product>, DomainError>;

    /// At most limit rows from offset, by primary key, and how many there are.
    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Product>, DomainError>;

    /// Stores a new row; the values the database fills are read back.
    async fn insert(&self, entity: Product) -> Result<Product, DomainError>;

    /// Stores the changes made to a row.
    async fn update(&self, entity: Product) -> Result<Product, DomainError>;

    /// Removes a row.
    async fn delete(&self, entity: &Product) -> Result<(), DomainError>;

    /// Adds an item to patterns, and gives the row as it is then, if there is one.
    async fn add_pattern(&self, id: String, pattern: mongodb::bson::Bson) -> Result<Option<Product>, DomainError>;

    /// Removes an item from patterns that has this size, and gives the row as it is then, if there is one.
    async fn remove_pattern(&self, id: String, position: usize, size: usize) -> Result<Option<Product>, DomainError>;

    /// Adds an item to parts, and gives the row as it is then, if there is one.
    async fn add_part(&self, id: String, part: crate::entities::product::ProductPart) -> Result<Option<Product>, DomainError>;

    /// Removes an item from parts that has this size, and gives the row as it is then, if there is one.
    async fn remove_part(&self, id: String, position: usize, size: usize) -> Result<Option<Product>, DomainError>;
}

/// Keeps products rows in the database, through the MongoDB driver: on the connection of the unit of work, or in its transaction.
pub struct MongoProductRepository<'a> {
    db: &'a Db,
}

impl<'a> MongoProductRepository<'a> {
    pub fn new(db: &'a Db) -> Self {
        Self { db }
    }
}

#[async_trait]
impl ProductRepository for MongoProductRepository<'_> {
    async fn find_by_id(&self, id: String) -> Result<Option<Product>, DomainError> {
        if !bson_values::is_object_id(&id) {
            return Ok(None);
        }
        let found = self.db.find_one("products", doc! { "_id": bson_values::of_object_id(&id)? }).await?;
        Ok(found.as_ref().map(Product::from_document).transpose()?)
    }

    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Product>, DomainError> {
        let total = self.db.count("products", doc! {}).await?;
        let found = if limit > 0 {
            self.db.find("products", doc! {}, doc! { "_id": 1 }, offset, limit).await?
        } else {
            Vec::new()
        };
        Ok(Page { items: found.iter().map(Product::from_document).collect::<Result<_, _>>()?, total, offset, limit })
    }

    async fn insert(&self, entity: Product) -> Result<Product, DomainError> {
        let mut entity = entity;
        entity.id = entity.id.or_else(|| Some(mongodb::bson::oid::ObjectId::new().to_hex()));
        let document = entity.to_document()?;
        self.db.insert("Product", "products", &document).await?;
        entity.loaded_document = Loaded(Some(document));
        Ok(entity)
    }

    async fn update(&self, entity: Product) -> Result<Product, DomainError> {
        let mut entity = entity;
        let now = entity.to_document()?;
        let changes = bson_values::changes(entity.loaded_document.0.as_ref(), &now, &["sku", "price", "stock", "weight", "big", "created", "reference", "picture", "key", "pattern", "patterns", "text", "parts", "low"]);
        if !changes.is_empty() {
            self.db.update("Product", "products", doc! { "_id": now.get("_id").cloned() }, changes).await?;
        }
        entity.loaded_document = Loaded(Some(now));
        Ok(entity)
    }

    async fn delete(&self, entity: &Product) -> Result<(), DomainError> {
        let id = entity.id.clone().expect("id is set");
        self.db.delete("Product", "products", doc! { "_id": bson_values::of_object_id(&id)? }).await
    }

    async fn add_pattern(&self, id: String, pattern: mongodb::bson::Bson) -> Result<Option<Product>, DomainError> {
        if !bson_values::is_object_id(&id) {
            return Ok(None);
        }
        let change = doc! { "$push": { "patterns": bson_values::of_any(&pattern)? } };
        let changed = self.db.change("Product", "products", doc! { "_id": bson_values::of_object_id(&id)? }, change).await?;
        Ok(changed.as_ref().map(Product::from_document).transpose()?)
    }

    async fn remove_pattern(&self, id: String, position: usize, size: usize) -> Result<Option<Product>, DomainError> {
        if !bson_values::is_object_id(&id) {
            return Ok(None);
        }
        let head = doc! { "$slice": ["$patterns", position as i64] };
        let tail = doc! { "$slice": ["$patterns", position as i64 + 1, size.max(1) as i64] };
        let change = vec![doc! { "$set": { "patterns": { "$concatArrays": [head, tail] } } }];
        let changed = self.db.change("Product", "products", doc! { "_id": bson_values::of_object_id(&id)?, "patterns": { "$size": size as i64 } }, change).await?;
        Ok(changed.as_ref().map(Product::from_document).transpose()?)
    }

    async fn add_part(&self, id: String, part: crate::entities::product::ProductPart) -> Result<Option<Product>, DomainError> {
        if !bson_values::is_object_id(&id) {
            return Ok(None);
        }
        let change = doc! { "$push": { "parts": bson_values::of_nested(crate::entities::product::ProductPart::to_document)(&part)? } };
        let changed = self.db.change("Product", "products", doc! { "_id": bson_values::of_object_id(&id)? }, change).await?;
        Ok(changed.as_ref().map(Product::from_document).transpose()?)
    }

    async fn remove_part(&self, id: String, position: usize, size: usize) -> Result<Option<Product>, DomainError> {
        if !bson_values::is_object_id(&id) {
            return Ok(None);
        }
        let head = doc! { "$slice": ["$parts", position as i64] };
        let tail = doc! { "$slice": ["$parts", position as i64 + 1, size.max(1) as i64] };
        let change = vec![doc! { "$set": { "parts": { "$concatArrays": [head, tail] } } }];
        let changed = self.db.change("Product", "products", doc! { "_id": bson_values::of_object_id(&id)?, "parts": { "$size": size as i64 } }, change).await?;
        Ok(changed.as_ref().map(Product::from_document).transpose()?)
    }
}

