}

#[async_trait]
impl ProductRepository for MemoryProductRepository {
    async fn find_by_id(&self, id: String) -> Result<Option<Product>, DomainError> {
        Ok(self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)))
    }

    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Product>, DomainError> {
        let rows = self.visible();
        let total = rows.len() as u64;
        Ok(Page { items: rows.into_iter().skip(offset as usize).take(limit as usize).collect(), total, offset, limit })
    }

    async fn insert(&self, entity: Product) -> Result<Product, DomainError> {
        let mut entity = entity;
        entity.id = entity.id.or_else(|| Some(mongodb::bson::oid::ObjectId::new().to_hex()));
        self.store(&entity);
        Ok(entity)
    }

    async fn update(&self, entity: Product) -> Result<Product, DomainError> {
        self.store(&entity);
        Ok(entity)
    }

    async fn delete(&self, entity: &Product) -> Result<(), DomainError> {
        self.rows.lock().unwrap().retain(|row| key_of(row) != key_of(entity));
        Ok(())
    }

    async fn add_pattern(&self, id: String, pattern: mongodb::bson::Bson) -> Result<Option<Product>, DomainError> {
        let Some(mut found) = self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)) else {
            return Ok(None);
        };
        found.patterns.get_or_insert_default().push(pattern);
        self.store(&found);
        Ok(Some(found))
    }

    async fn remove_pattern(&self, id: String, position: usize, size: usize) -> Result<Option<Product>, DomainError> {
        let Some(mut found) = self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)) else {
            return Ok(None);
        };
        let items = found.patterns.get_or_insert_default();
        if items.len() != size || position >= size {
            return Ok(None);
        }
        items.remove(position);
        self.store(&found);
        Ok(Some(found))
    }

    async fn add_part(&self, id: String, part: crate::entities::product::ProductPart) -> Result<Option<Product>, DomainError> {
        let Some(mut found) = self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)) else {
            return Ok(None);
        };
        found.parts.get_or_insert_default().push(part);
        self.store(&found);
        Ok(Some(found))
    }

    async fn remove_part(&self, id: String, position: usize, size: usize) -> Result<Option<Product>, DomainError> {
        let Some(mut found) = self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)) else {
            return Ok(None);
        };
        let items = found.parts.get_or_insert_default();
        if items.len() != size || position >= size {
            return Ok(None);
        }
        items.remove(position);
        self.store(&found);
        Ok(Some(found))
    }
}

