//! The service of the "audit-log" table.

use crate::common::Page;
use crate::dtos::audit_log::{AuditLogCreate, AuditLogRead, AuditLogUpdate};
use crate::entities::audit_log::AuditLog;
use crate::errors::{DomainError, FieldError};
use crate::unit_of_work::UnitOfWork;
use std::sync::Arc;

/// Operations on audit-log. Repositories commit every write.
pub struct AuditLogService {
    unit_of_work: Arc<dyn UnitOfWork>,
}

impl AuditLogService {
    pub fn new(unit_of_work: Arc<dyn UnitOfWork>) -> Self {
        Self { unit_of_work }
    }

    /// Stores a new AuditLog after checking it.
    pub async fn create_audit_log(&self, data: AuditLogCreate) -> Result<AuditLogRead, DomainError> {
        let values = Values { id: data.id.map(Some), at: data.at.map(Some), by: data.by.map(Some) };
        let uow = self.unit_of_work.as_ref();
        check_values(uow, &values, None).await?;
        let mut entity = AuditLog::default();
        apply_values(&mut entity, &values);
        let created = uow.audit_log().insert(entity).await?;
        Ok(read(created))
    }

    /// The AuditLog with this key; NotFound when there is none.
    pub async fn get_audit_log(&self, id: String) -> Result<AuditLogRead, DomainError> {
        find(self.unit_of_work.as_ref(), id).await.map(read)
    }

    /// A page of audit-log, by primary key.
    pub async fn list_audit_logs(&self, offset: u64, limit: u64) -> Result<Page<AuditLogRead>, DomainError> {
        self.unit_of_work.audit_log().list(offset, limit).await.map(|page| page.map(read))
    }

    /// Changes the given values of a AuditLog.
    pub async fn update_audit_log(&self, id: String, changes: AuditLogUpdate) -> Result<AuditLogRead, DomainError> {
        let values = given(changes);
        let uow = self.unit_of_work.as_ref();
        let mut current = find(uow, id).await?;
        check_values(uow, &values, Some(&current)).await?;
        apply_values(&mut current, &values);
        let updated = uow.audit_log().update(current).await?;
        Ok(read(updated))
    }

    /// Deletes a AuditLog.
    pub async fn delete_audit_log(&self, id: String) -> Result<(), DomainError> {
        let uow = self.unit_of_work.as_ref();
        let current = find(uow, id).await?;
        uow.audit_log().delete(&current).await?;
        Ok(())
    }
}

/// The values a create or an update gives, by field: None when not given, Some(None) when given empty.
#[derive(Default)]
struct Values {
    id: Option<Option<String>>,
    at: Option<Option<chrono::DateTime<chrono::Utc>>>,
    by: Option<Option<mongodb::bson::Bson>>,
}

/// Checks the values against the rules of the "audit-log" table, and the rows they point to; ValidationFailed lists every problem.
async fn validate(_uow: &dyn UnitOfWork, values: &Values, current: Option<&AuditLog>) -> Result<(), DomainError> {
    let creating = current.is_none();
    let mut errors = Vec::new();
    match values.id.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.id.is_some() {
                errors.push(FieldError::new("_id", "is required"));
            }
        }
        Some(_) => {}
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(DomainError::ValidationFailed { entity: "AuditLog".to_string(), errors })
    }
}

/// Every check before a write: the values, the rows they point to, the unique values.
async fn check_values(uow: &dyn UnitOfWork, values: &Values, current: Option<&AuditLog>) -> Result<(), DomainError> {
    validate(uow, values, current).await?;
    Ok(())
}

/// Sets the given values on the entity.
fn apply_values(entity: &mut AuditLog, values: &Values) {
    if let Some(value) = &values.id {
        entity.id = value.clone();
    }
    if let Some(value) = &values.at {
        entity.at = *value;
    }
    if let Some(value) = &values.by {
        entity.by = value.clone();
    }
}

/// The values an update gives, by field.
fn given(changes: AuditLogUpdate) -> Values {
    Values { at: changes.at.given(), by: changes.by.given(), ..Default::default() }
}

/// The AuditLog with this key; NotFound when there is none.
async fn find(uow: &dyn UnitOfWork, id: String) -> Result<AuditLog, DomainError> {
    uow.audit_log().find_by_id(id.clone()).await?.ok_or_else(|| DomainError::not_found("AuditLog", id))
}

/// The AuditLog as services return it.
fn read(entity: AuditLog) -> AuditLogRead {
    AuditLogRead {
        id: entity.id.expect("id is set"),
        at: entity.at,
        by: entity.by,
    }
}

