//! The service of the "products" table.

use crate::common::Page;
use crate::dtos::product::{ProductCreate, ProductRead, ProductUpdate};
use crate::entities::product::Product;
use crate::errors::{DomainError, FieldError};
use crate::unit_of_work::UnitOfWork;
use std::sync::Arc;

/// Operations on products. Repositories commit every write.
pub struct ProductService {
    unit_of_work: Arc<dyn UnitOfWork>,
}

impl ProductService {
    pub fn new(unit_of_work: Arc<dyn UnitOfWork>) -> Self {
        Self { unit_of_work }
    }

    /// Stores a new Product after checking it.
    pub async fn create_product(&self, data: ProductCreate) -> Result<ProductRead, DomainError> {
        let values = Values { sku: data.sku.map(Some), price: data.price.map(Some), stock: data.stock.map(Some), weight: data.weight.map(Some), big: data.big.map(Some), created: data.created.map(Some), reference: data.reference.map(Some), picture: data.picture.map(Some), key: data.key.map(Some), pattern: data.pattern.map(Some), patterns: data.patterns.map(Some), text: data.text.map(Some), parts: data.parts.map(Some), low: data.low.map(Some) };
        let uow = self.unit_of_work.as_ref();
        check_values(uow, &values, None).await?;
        let mut entity = Product::default();
        apply_values(&mut entity, &values);
        let created = uow.products().insert(entity).await?;
        Ok(read(created))
    }

    /// The Product with this key; NotFound when there is none.
    pub async fn get_product(&self, id: String) -> Result<ProductRead, DomainError> {
        find(self.unit_of_work.as_ref(), id).await.map(read)
    }

    /// A page of products, by primary key.
    pub async fn list_products(&self, offset: u64, limit: u64) -> Result<Page<ProductRead>, DomainError> {
        self.unit_of_work.products().list(offset, limit).await.map(|page| page.map(read))
    }

    /// Changes the given values of a Product.
    pub async fn update_product(&self, id: String, changes: ProductUpdate) -> Result<ProductRead, DomainError> {
        let values = given(changes);
        let uow = self.unit_of_work.as_ref();
        let mut current = find(uow, id).await?;
        check_values(uow, &values, Some(&current)).await?;
        apply_values(&mut current, &values);
        let updated = uow.products().update(current).await?;
        Ok(read(updated))
    }

    /// Deletes a Product.
    pub async fn delete_product(&self, id: String) -> Result<(), DomainError> {
        let uow = self.unit_of_work.as_ref();
        let current = find(uow, id).await?;
        uow.products().delete(&current).await?;
        Ok(())
    }

    /// Adds an item to patterns.
    pub async fn add_pattern(&self, id: String, pattern: mongodb::bson::Bson) -> Result<ProductRead, DomainError> {
        let uow = self.unit_of_work.as_ref();
        find(uow, id.clone()).await?;
        let changed = uow.products().add_pattern(id.clone(), pattern).await?.ok_or_else(|| DomainError::not_found("Product", id))?;
        Ok(read(changed))
    }

    /// Removes an item from patterns, by its position.
    pub async fn remove_pattern(&self, id: String, position: usize) -> Result<ProductRead, DomainError> {
        let uow = self.unit_of_work.as_ref();
        let current = find(uow, id.clone()).await?;
        if !(position < current.patterns.as_deref().unwrap_or_default().len()) {
            return Err(DomainError::not_found("Pattern", position));
        }
        let size = current.patterns.as_deref().unwrap_or_default().len();
        let changed = uow.products().remove_pattern(id.clone(), position, size).await?.ok_or_else(|| DomainError::conflict("Product", "was changed by someone else since it was read", &["patterns"]))?;
        Ok(read(changed))
    }

    /// Adds an item to parts.
    pub async fn add_part(&self, id: String, part: crate::entities::product::ProductPart) -> Result<ProductRead, DomainError> {
        let mut errors: Vec<FieldError> = Vec::new();
        check_product_part(&part, "parts", &mut errors);
        if !errors.is_empty() {
            return Err(DomainError::ValidationFailed { entity: "Product".to_string(), errors });
        }
        let uow = self.unit_of_work.as_ref();
        find(uow, id.clone()).await?;
        let changed = uow.products().add_part(id.clone(), part).await?.ok_or_else(|| DomainError::not_found("Product", id))?;
        Ok(read(changed))
    }

    /// Removes an item from parts, by its position.
    pub async fn remove_part(&self, id: String, position: usize) -> Result<ProductRead, DomainError> {
        let uow = self.unit_of_work.as_ref();
        let current = find(uow, id.clone()).await?;
        if !(position < current.parts.as_deref().unwrap_or_default().len()) {
            return Err(DomainError::not_found("Part", position));
        }
        let size = current.parts.as_deref().unwrap_or_default().len();
        let changed = uow.products().remove_part(id.clone(), position, size).await?.ok_or_else(|| DomainError::conflict("Product", "was changed by someone else since it was read", &["parts"]))?;
        Ok(read(changed))
    }
}

/// The values a create or an update gives, by field: None when not given, Some(None) when given empty.
#[derive(Default)]
struct Values {
    sku: Option<Option<String>>,
    price: Option<Option<rust_decimal::Decimal>>,
    stock: Option<Option<f64>>,
    weight: Option<Option<f64>>,
    big: Option<Option<i64>>,
    created: Option<Option<chrono::DateTime<chrono::Utc>>>,
    reference: Option<Option<uuid::Uuid>>,
    picture: Option<Option<Vec<u8>>>,
    key: Option<Option<uuid::Uuid>>,
    pattern: Option<Option<mongodb::bson::Bson>>,
    patterns: Option<Option<Vec<mongodb::bson::Bson>>>,
    text: Option<Option<String>>,
    parts: Option<Option<Vec<crate::entities::product::ProductPart>>>,
    low: Option<Option<i64>>,
}

/// Checks the values against the rules of the "products" table, and the rows they point to; ValidationFailed lists every problem.
async fn validate(_uow: &dyn UnitOfWork, values: &Values, _current: Option<&Product>) -> Result<(), DomainError> {
    let mut errors = Vec::new();
    if let Some(value) = values.parts.as_ref().and_then(|value| value.as_ref()) {
        for (i0, item0) in value.iter().enumerate() {
            check_product_part(item0, &format!("parts.{i0}"), &mut errors);
        }
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(DomainError::ValidationFailed { entity: "Product".to_string(), errors })
    }
}

/// Every check before a write: the values, the rows they point to, the unique values.
async fn check_values(uow: &dyn UnitOfWork, values: &Values, current: Option<&Product>) -> Result<(), DomainError> {
    validate(uow, values, current).await?;
    Ok(())
}

/// Sets the given values on the entity.
fn apply_values(entity: &mut Product, values: &Values) {
    if let Some(value) = &values.sku {
        entity.sku = value.clone();
    }
    if let Some(value) = &values.price {
        entity.price = *value;
    }
    if let Some(value) = &values.stock {
        entity.stock = *value;
    }
    if let Some(value) = &values.weight {
        entity.weight = *value;
    }
    if let Some(value) = &values.big {
        entity.big = *value;
    }
    if let Some(value) = &values.created {
        entity.created = *value;
    }
    if let Some(value) = &values.reference {
        entity.reference = *value;
    }
    if let Some(value) = &values.picture {
        entity.picture = value.clone();
    }
    if let Some(value) = &values.key {
        entity.key = *value;
    }
    if let Some(value) = &values.pattern {
        entity.pattern = value.clone();
    }
    if let Some(value) = &values.patterns {
        entity.patterns = value.clone();
    }
    if let Some(value) = &values.text {
        entity.text = value.clone();
    }
    if let Some(value) = &values.parts {
        entity.parts = value.clone();
    }
    if let Some(value) = &values.low {
        entity.low = *value;
    }
}

/// What a ProductPart does not follow of its rules, each with the path of its field.
fn check_product_part(value: &crate::entities::product::ProductPart, path: &str, errors: &mut Vec<FieldError>) {
    if let Some(held) = &value.inner {
        check_product_part_inner(held, &format!("{path}.inner"), errors);
    }
}

/// What a ProductPartInner does not follow of its rules, each with the path of its field.
fn check_product_part_inner(_value: &crate::entities::product::ProductPartInner, _path: &str, _errors: &mut Vec<FieldError>) {
}

/// The values an update gives, by field.
fn given(changes: ProductUpdate) -> Values {
    Values { sku: changes.sku.given(), price: changes.price.given(), stock: changes.stock.given(), weight: changes.weight.given(), big: changes.big.given(), created: changes.created.given(), reference: changes.reference.given(), picture: changes.picture.given(), key: changes.key.given(), pattern: changes.pattern.given(), patterns: changes.patterns.given(), text: changes.text.given(), parts: changes.parts.given(), low: changes.low.given() }
}

/// The Product with this key; NotFound when there is none.
async fn find(uow: &dyn UnitOfWork, id: String) -> Result<Product, DomainError> {
    uow.products().find_by_id(id.clone()).await?.ok_or_else(|| DomainError::not_found("Product", id))
}

/// The Product as services return it.
fn read(entity: Product) -> ProductRead {
    ProductRead {
        id: entity.id.expect("id is set"),
        sku: entity.sku,
        price: entity.price,
        stock: entity.stock,
        weight: entity.weight,
        big: entity.big,
        created: entity.created,
        reference: entity.reference,
        picture: entity.picture,
        key: entity.key,
        pattern: entity.pattern,
        patterns: entity.patterns,
        text: entity.text,
        parts: entity.parts,
        low: entity.low,
    }
}

