/// A valid Product that is not stored yet; n makes its unique values differ.
pub fn new_product(n: i32) -> Product {
    Product {
        sku: Some(format!("sku-{n}")),
        price: Some(rust_decimal::Decimal::new(i64::from(n % 10000) * 100 + 50, 2)),
        stock: Some(f64::from(n) + 0.5),
        weight: Some(f64::from(n) + 0.5),
        big: Some(i64::from(n)),
        created: Some(chrono::NaiveDate::from_ymd_opt(2026, 1, (n % 28 + 1) as u32).expect("a date").and_hms_opt(12, 0, 0).expect("a time").and_utc()),
        reference: Some(uuid::Uuid::from_u128(n as u128)),
        picture: Some(vec![n as u8]),
        key: Some(uuid::Uuid::from_u128(n as u128)),
        pattern: Some(mongodb::bson::bson!({ "n": n })),
        patterns: Some(Vec::new()),
        text: Some(format!("text-{n}")),
        parts: Some(vec![new_product_part(n)]),
        low: Some(i64::from(n)),
        ..Default::default()
    }
}

