    let created = service.create_product(create_of(row)).await.expect("a create");
    let before = created.patterns.as_ref().map_or(0, Vec::len);
    let n = 7;
    let item: mongodb::bson::Bson = mongodb::bson::bson!({ "n": n });
    let added = service.add_pattern(created.id.clone(), item).await.expect("a write");
    assert_eq!(before + 1, added.patterns.as_ref().map_or(0, Vec::len));
    let removed = service.remove_pattern(created.id.clone(), before).await.expect("a write");
    assert_eq!(before, removed.patterns.as_ref().map_or(0, Vec::len));
    assert!(matches!(service.remove_pattern(created.id.clone(), 99).await, Err(DomainError::NotFound { .. })));
}

#[tokio::test]
async fn adds_and_removes_one_item_of_parts() {
    let uow = Arc::new(MemoryUnitOfWork::default());
