}

/// The create DTO of a row the factories made.
fn create_of(row: Product) -> ProductCreate {
    ProductCreate { sku: row.sku, price: row.price, stock: row.stock, weight: row.weight, big: row.big, created: row.created, reference: row.reference, picture: row.picture, key: row.key, pattern: row.pattern, patterns: row.patterns, text: row.text, parts: row.parts, low: row.low }
}
